	private void assertResidualFilterTeachesNextPlan(String profile, String query, int firstSubject,
			boolean trackResultSize) throws Exception {
		store.setTrackResultSize(trackResultSize);
		LmdbLearnedFilterSelectivity learned = store.getBackingStore().learnedFilterSelectivity();
		assertThat(learned.size()).as("fresh fixture has no learned observations").isZero();

		try (SailRepositoryConnection connection = repository.getConnection();
				SailDataset dataset = FilterLearningFullReadView.open(store.getBackingStore(),
						IsolationLevels.SNAPSHOT_READ)) {
			PreparedQuery prepared = prepareActualQuery(connection, dataset, query, trackResultSize);
			Filter initialPlanFilter = firstFilter(prepared.optimized());
			assertThat(initialPlanFilter).as("the original plan has a filter before feedback is collected").isNotNull();
			String initialPlannedSource = initialPlanFilter
					.getStringMetricPlanned(TelemetryMetricNames.FILTER_SELECTIVITY_SOURCE);
			Double initialPlannedRatio = initialPlanFilter.getDoubleMetricsPlanned()
					.get(TelemetryMetricNames.PLANNED_FILTER_PASS_RATIO);
			assertThat(initialPlannedSource).as("the original planned filter source is available before feedback")
					.isNotBlank();
			assertThat(initialPlannedRatio).as("the original planned filter ratio is finite and bounded")
					.isNotNull()
					.isFinite()
					.isBetween(0.0d, 1.0d);
			emitInitialFilterTelemetry(profile, initialPlannedSource, initialPlannedRatio);
			List<Filter> filters = findFilters(prepared.optimized());
			System.out.println("RESIDUAL_PLAN\t" + profile + "\tfilters=" + filters.size()
					+ "\tmathExprs=" + filters.stream().mapToInt(filter -> countMathExprs(filter.getCondition())).sum());
			List<String> actualSubjects = evaluateSubjects(prepared);
			assertThat(actualSubjects).as("the complete residual-filter subject bag")
					.containsExactlyElementsOf(expectedSubjects(firstSubject));

			Filter observedFilter = filters.isEmpty() ? null : filters.get(0);
			assertThat(observedFilter).as("the actual optimized query retains its residual Filter").isNotNull();
			MathExpr mathExpr = firstMathExpr(observedFilter.getCondition());
			assertThat(mathExpr).as("the residual condition retains the expected arithmetic dependency").isNotNull();
			assertThat(mathExpr.getOperator()).isEqualTo(MathExpr.MathOp.PLUS);
			assertThat(mathExpr.getLeftArg()).isInstanceOf(Var.class);
			assertThat(((Var) mathExpr.getLeftArg()).getName()).isEqualTo("v");
			assertThat(mathExpr.getRightArg()).isInstanceOf(ValueConstant.class);
			assertThat(((ValueConstant) mathExpr.getRightArg()).getValue().stringValue()).isEqualTo("1");
			List<String> conditionVariables = new ArrayList<>();
			observedFilter.getCondition().visit(new AbstractQueryModelVisitor<RuntimeException>() {
				@Override
				public void meet(Var node) {
					conditionVariables.add(node.getName());
					super.meet(node);
				}
			});
			assertThat(conditionVariables).contains("v");

			RuntimeFeedbackContract contract = observedFilter.getRuntimeFeedbackContract();
			assertThat(contract).as("the compiler-owned feedback contract reaches the real prepared filter")
					.isNotNull();
			assertThat(contract.admissionFlags()).isEqualTo(RuntimeFeedbackContract.ADMIT_FILTER);
			assertThat(contract.semanticKind()).isEqualTo(RuntimeFeedbackContract.SemanticKind.FILTER);
			assertThat(prepared.statistics().shouldTrackCostFeedback(observedFilter)).isTrue();
			assertThat(prepared.strategy().isTrackResultSize()).isEqualTo(trackResultSize);

			assertThat(learned.size()).as("complete execution of the actual residual filter publishes evidence")
					.isPositive();
			SailTupleQuery nextQuery = connection.prepareTupleQuery(QueryLanguage.SPARQL, query, null);
			TupleExpr nextRoot = nextQuery.getParsedQuery().getTupleExpr().clone();
			assertThat(nextRoot).isInstanceOf(QueryRoot.class);
			TupleExpr nextPlan = prepared.strategy().optimize(nextRoot, prepared.statistics(), nextQuery.getBindings());
			emitNextPlanCacheMetadata(profile, nextPlan);
			String pipelineCacheHit = nextPlan.getStringMetricPlanned("optimizer.pipelinePlanCacheHit");
			assertThat(pipelineCacheHit).as("the actual identical-query pipeline-cache result is explicit")
					.isIn("true", "false");
			if ("true".equals(pipelineCacheHit)) {
				assertThat(nextPlan.getStringMetricPlanned("optimizer.planCacheLookupOutcome"))
						.isEqualTo("USE_AND_REFRESH");
				assertThat(nextPlan.getStringMetricPlanned("optimizer.planCacheRefreshReason"))
						.isEqualTo("outside-stability-envelope");
				assertThat(nextPlan.getStringMetricPlanned("optimizer.planCacheQualityState"))
						.isEqualTo("SUSPECT");
				assertThat(nextPlan.getStringMetricPlanned("optimizer.planCacheStabilityEnvelopeResult"))
						.isEqualTo("OUTSIDE");
			}
			Filter plannedFilter = firstFilter(nextPlan);
			assertThat(plannedFilter).isNotNull();
			FilterPassEstimate estimate = prepared.statistics().estimateFilterPass(plannedFilter);
			assertThat(estimate.getSource()).isIn(FilterPassEstimate.Source.LEARNED_FILTER,
					FilterPassEstimate.Source.LEARNED_TEMPLATE, FilterPassEstimate.Source.LEARNED_PATTERN);
			assertThat(estimate.getPassRatio()).isCloseTo(20.0d / 1000.0d, within(1.0e-12d));
			assertThat(estimate.getEvidenceCount()).isEqualTo(1000L);
			String plannedSource = plannedFilter.getStringMetricPlanned(TelemetryMetricNames.FILTER_SELECTIVITY_SOURCE);
			Double plannedRatio = plannedFilter.getDoubleMetricsPlanned()
					.get(TelemetryMetricNames.PLANNED_FILTER_PASS_RATIO);
			if ("true".equals(pipelineCacheHit)) {
				assertThat(plannedSource).as("a cached plan retains its initial-build telemetry")
						.isEqualTo(initialPlannedSource);
				assertThat(plannedRatio).isEqualTo(initialPlannedRatio);
			} else {
				assertThat(plannedSource).as("a fresh plan exposes the learned residual estimate")
						.isIn("learned_filter", "learned_template", "learned_pattern");
				assertThat(plannedRatio).as("a fresh plan carries the same evidence-backed learned ratio")
						.isNotNull()
						.isCloseTo(20.0d / 1000.0d, within(1.0e-12d));
			}

			assertDifferentProjectionUsesLearnedResidual(connection, prepared, profile, query, firstSubject);
		}
	}

	private void assertDifferentProjectionUsesLearnedResidual(SailRepositoryConnection connection,
			PreparedQuery trainedQuery, String profile, String originalQuery, int firstSubject) throws Exception {
		String projectionQueryText = originalQuery.replace("SELECT ?s WHERE", "SELECT ?s ?v WHERE");
		assertThat(projectionQueryText).isNotEqualTo(originalQuery);
		SailTupleQuery projectionQuery = connection.prepareTupleQuery(QueryLanguage.SPARQL, projectionQueryText, null);
		TupleExpr projectionRoot = projectionQuery.getParsedQuery().getTupleExpr().clone();
		assertThat(projectionRoot).as("the changed projection is still a real repository QueryRoot")
				.isInstanceOf(QueryRoot.class);
		TupleExpr projectionPlan = trainedQuery.strategy().optimize(projectionRoot, trainedQuery.statistics(),
				projectionQuery.getBindings());
		emitNextPlanCacheMetadata(profile + "-different-projection", projectionPlan);
		assertThat(projectionPlan.getStringMetricPlanned("optimizer.pipelinePlanCacheHit"))
				.as("a different projection has a distinct structural pipeline-cache identity")
				.isEqualTo("false");
		Filter projectedFilter = firstFilter(projectionPlan);
		assertThat(projectedFilter).as("the changed projection retains the same residual Filter").isNotNull();
		Filter originalFilter = firstFilter(trainedQuery.optimized());
		FilterSurfaceKey projectedSurface = FilterSurfaceKey.exact(projectedFilter);
		FilterSurfaceKey originalSurface = FilterSurfaceKey.exact(originalFilter);
		assertThat(originalSurface).as("the original filter has a complete exact evidence identity").isNotNull();
		assertThat(projectedSurface).as("the projected filter has a complete exact evidence identity").isNotNull();
		assertThat(projectedSurface).as("filter evidence identity excludes the outer projection")
				.isEqualTo(originalSurface);
		MathExpr projectedMath = firstMathExpr(projectedFilter.getCondition());
		assertThat(projectedMath).isNotNull();
		assertThat(projectedMath.getOperator()).isEqualTo(MathExpr.MathOp.PLUS);
		assertThat(projectedMath.getLeftArg()).isInstanceOf(Var.class);
		assertThat(((Var) projectedMath.getLeftArg()).getName()).isEqualTo("v");
		FilterPassEstimate estimate = trainedQuery.statistics().estimateFilterPass(projectedFilter);
		assertThat(estimate.getSource()).isIn(FilterPassEstimate.Source.LEARNED_FILTER,
				FilterPassEstimate.Source.LEARNED_TEMPLATE, FilterPassEstimate.Source.LEARNED_PATTERN);
		assertThat(estimate.getPassRatio()).isCloseTo(20.0d / 1000.0d, within(1.0e-12d));
		assertThat(estimate.getEvidenceCount()).isEqualTo(1000L);
		assertThat(projectedFilter.getStringMetricPlanned(TelemetryMetricNames.FILTER_SELECTIVITY_SOURCE))
				.isIn("learned_filter", "learned_template", "learned_pattern");
		assertThat(projectedFilter.getDoubleMetricPlanned(TelemetryMetricNames.PLANNED_FILTER_PASS_RATIO))
				.isCloseTo(20.0d / 1000.0d, within(1.0e-12d));

		QueryEvaluationStep projectionStep = trainedQuery.strategy().precompile(projectionPlan);
		List<SubjectValue> actualRows = evaluateSubjectValues(projectionStep, projectionQuery.getBindings());
		assertThat(actualRows).as("the different projection returns the exact complete subject/literal bag")
				.containsExactlyInAnyOrderElementsOf(expectedSubjectValues(connection.getValueFactory(), firstSubject));
		assertThat(actualRows).allSatisfy(row -> assertThat(row.value().getDatatype()).isEqualTo(XSD.INT));
	}

	private static void emitInitialFilterTelemetry(String profile, String source, Double passRatio) {
		System.out.println("INITIAL_FILTER_TELEMETRY\t" + profile
				+ "\tplannedSource=" + (source == null ? "UNKNOWN" : source)
				+ "\tplannedPassRatio=" + (passRatio == null ? "UNKNOWN" : passRatio));
	}

	private static void emitNextPlanCacheMetadata(String profile, TupleExpr plan) {
		System.out.println("PLAN_CACHE_TRACE\t" + profile
				+ "\tpipelinePlanCacheHit=" + plannedStringOrUnknown(plan, "optimizer.pipelinePlanCacheHit")
				+ "\tcascadesPlanCacheHit=" + plannedStringOrUnknown(plan, "optimizer.cascadesPlanCacheHit")
				+ "\tlookupOutcome=" + plannedStringOrUnknown(plan, "optimizer.planCacheLookupOutcome")
				+ "\trefreshReason=" + plannedStringOrUnknown(plan, "optimizer.planCacheRefreshReason")
				+ "\tvalidationResult=" + plannedStringOrUnknown(plan, "optimizer.planCacheValidationResult")
				+ "\tvalidationReason=" + plannedStringOrUnknown(plan, "optimizer.planCacheValidationReason")
				+ "\tqualityState=" + plannedStringOrUnknown(plan, "optimizer.planCacheQualityState")
				+ "\tstabilityEnvelope=" + plannedStringOrUnknown(plan, "optimizer.planCacheStabilityEnvelopeResult")
				+ "\tfamily=" + plannedDoubleOrUnknown(plan, "optimizer.planCacheFamily")
				+ "\tvariant=" + plannedDoubleOrUnknown(plan, "optimizer.planCacheVariant")
				+ "\tplanVersion=" + plannedDoubleOrUnknown(plan, "optimizer.planCachePlanVersion")
				+ "\tevidenceEpoch=" + plannedDoubleOrUnknown(plan, "optimizer.planCacheEvidenceEpoch"));
	}

	private static String plannedStringOrUnknown(TupleExpr node, String metric) {
		String value = node.getStringMetricsPlanned().get(metric);
		return value == null ? "UNKNOWN" : value;
	}

	private static String plannedDoubleOrUnknown(TupleExpr node, String metric) {
		Double value = node.getDoubleMetricsPlanned().get(metric);
		return value == null ? "UNKNOWN" : Double.toString(value);
	}

	private PreparedQuery prepareActualQuery(SailRepositoryConnection connection, SailDataset dataset, String query,
			boolean trackResultSize) throws Exception {
		SailTupleQuery tupleQuery = connection.prepareTupleQuery(QueryLanguage.SPARQL, query, null);
		TupleExpr completeQuery = tupleQuery.getParsedQuery().getTupleExpr().clone();
		assertThat(completeQuery).as("the real repository query retains its QueryRoot").isInstanceOf(QueryRoot.class);
		EvaluationStatistics statistics = store.getBackingStore().getEvaluationStatistics();
		SailDatasetTripleTermSource source = new SailDatasetTripleTermSource(store.getValueFactory(), dataset);
		assertThat(source.getClass()).isEqualTo(SailDatasetTripleTermSource.class);
		assertThat(source.getSnapshotEpoch()).as("the audited full-read source is pinned").isPresent();
		EvaluationStrategy evaluationStrategy = store.getConnectionEvaluationStrategyFactory().createEvaluationStrategy(
				tupleQuery.getActiveDataset(), source, statistics, store.getQueryExecutionPolicy());
		assertThat(evaluationStrategy).isInstanceOf(LmdbEvaluationStrategy.class)
				.isNotInstanceOf(LmdbNativeEvaluationStrategy.class);
		assertThat(evaluationStrategy.getQueryExecutionPolicy().experimentalQueryOptimizations()).isTrue();
		LmdbEvaluationStrategy strategy = (LmdbEvaluationStrategy) evaluationStrategy;
		strategy.setTrackResultSize(trackResultSize);
		assertThat(strategy.isTrackResultSize()).isEqualTo(trackResultSize);
		TupleExpr optimized = strategy.optimize(completeQuery, statistics, tupleQuery.getBindings());
		QueryEvaluationStep step = strategy.precompile(optimized);
		return new PreparedQuery(tupleQuery, strategy, statistics, optimized, step);
	}

	private List<String> evaluateSubjects(PreparedQuery prepared) {
		List<BindingSet> results = QueryResults.asList(prepared.step().evaluate(prepared.query().getBindings()));
		return results.stream()
				.map(bindingSet -> bindingSet.getValue("s").stringValue())
				.sorted()
				.toList();
	}

	private static List<SubjectValue> evaluateSubjectValues(QueryEvaluationStep step, BindingSet bindings) {
		return QueryResults.asList(step.evaluate(bindings)).stream()
				.map(bindingSet -> {
					Value subject = bindingSet.getValue("s");
					Value value = bindingSet.getValue("v");
					assertThat(subject).isNotNull();
					assertThat(value).as("the projected value remains a literal").isInstanceOf(Literal.class);
					return new SubjectValue(subject.stringValue(), (Literal) value);
				})
				.toList();
	}

	private static List<SubjectValue> expectedSubjectValues(ValueFactory valueFactory, int firstSubject) {
		return IntStream.range(firstSubject, firstSubject + 20)
				.mapToObj(value -> new SubjectValue(EX + "s" + value, valueFactory.createLiteral(value)))
				.toList();
	}

	private static List<String> expectedSubjects(int firstSubject) {
		List<String> expected = new ArrayList<>();
		for (int i = firstSubject; i < firstSubject + 20; i++) {
			expected.add(EX + "s" + i);
		}
		expected.sort(String::compareTo);
		return expected;
	}

	private static List<Filter> findFilters(TupleExpr expr) {
		List<Filter> found = new ArrayList<>();
		expr.visit(new AbstractQueryModelVisitor<RuntimeException>() {
			@Override
			public void meet(Filter node) {
				found.add(node);
				super.meet(node);
			}
		});
		return found;
	}

	private static Filter firstFilter(TupleExpr expr) {
		List<Filter> filters = findFilters(expr);
		return filters.isEmpty() ? null : filters.get(0);
	}

	private static MathExpr firstMathExpr(ValueExpr expr) {
		MathExpr[] found = new MathExpr[1];
		expr.visit(new AbstractQueryModelVisitor<RuntimeException>() {
			@Override
			public void meet(MathExpr node) {
				if (found[0] == null) {
					found[0] = node;
				}
				super.meet(node);
			}
		});
		return found[0];
	}

	private static int countMathExprs(ValueExpr expr) {
		int[] count = new int[1];
		expr.visit(new AbstractQueryModelVisitor<RuntimeException>() {
			@Override
			public void meet(MathExpr node) {
				count[0]++;
				super.meet(node);
			}
		});
		return count[0];
	}

	private static List<BindingSetAssignment> findAssignments(TupleExpr expr) {
		List<BindingSetAssignment> found = new ArrayList<>();
		expr.visit(new AbstractQueryModelVisitor<RuntimeException>() {
			@Override
			public void meet(BindingSetAssignment node) {
				found.add(node);
				super.meet(node);
			}
		});
		return found;
	}

	private static boolean containsPlannedStringMetric(QueryModelNode queryModelNode, String metricName,
			String expectedFragment) {
		boolean[] found = { false };
		queryModelNode.visit(new AbstractQueryModelVisitor<RuntimeException>() {
			@Override
			protected void meetNode(QueryModelNode node) {
				String metricValue = node.getStringMetricPlanned(metricName);
				if (metricValue != null && metricValue.contains(expectedFragment)) {
					found[0] = true;
					return;
				}
				super.meetNode(node);
			}
		});
		return found[0];
	}

